53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const COMPONENT_TYPES = ["rune", "moonstone"];
65	const COMPONENT_BLOCK_SIZE = 3;
66	const COMPONENT_BLOCK_PREMIUM = 60;
67	
68	const isComponent = (item: QuoteItem): boolean =>
69	  COMPONENT_TYPES.includes(item.type);
70	
71	// Pricing rule: a block of exactly 3 alike components costs a flat block premium.
72	const componentsPremium = (items: QuoteItem[], type: string): number => {
73	  const count = items.filter((item) => item.type === type).length;
74	  return count === COMPONENT_BLOCK_SIZE
75	    ? COMPONENT_BLOCK_PREMIUM
76	    : count * BASE_PREMIUMS[type];
77	};
78	
79	const quotePremium = (items: QuoteItem[]): number => {
80	  const allComponentsPremium = COMPONENT_TYPES.reduce(
81	    (sum, type) => sum + componentsPremium(items, type),
82	    0
83	  );
84	  const mainItemsPremium = items
85	    .filter((item) => !isComponent(item))
86	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
87	  const policyBasePremium = allComponentsPremium + mainItemsPremium;
88	  // 10% surcharge computed as base/10 (multiplying by 1.1 introduces float noise)
89	  const firstInsuranceSurcharge = policyBasePremium / 10;
90	  return Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
91	};
92	
93	export const runScenario = (scenario: Scenario): ScenarioResult => {
94	  const quoteStep = scenario.steps[0] as QuoteStep;
95	  return { results: [{ premium: quotePremium(quoteStep.items) }] };
96	};
